function csvField(v) {
  const s = v === null || v === undefined ? "" : String(v);
  return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function buatBarisCsv(header, obj) {
  return header.map((h) => csvField(obj[h])).join(",");
}
function parseTanggalFleksibel(raw) {
  if (raw === null || raw === undefined || raw === "") return null;
  const s = String(raw).trim();
  let m = /^(\d{4})-(\d{2})-(\d{2})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?/.exec(s);
  if (m) return Date.UTC(+m[1], +m[2] - 1, +m[3], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
  m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?)?/.exec(s);
  if (m) return Date.UTC(+m[3], +m[1] - 1, +m[2], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
  return null;
}
// "Sekarang" dalam jam dinding Asia/Jakarta, dihitung sebagai UTC+0 palsu
// supaya bisa dibandingkan apple-to-apple dengan parseTanggalFleksibel (yang
// juga membaca digit jam mentah TANPA konversi timezone apa pun) -- cukup
// akurat untuk jendela lookback per hari, TIDAK dipakai untuk simpan ke DB.
function sekarangJakartaMs() {
  return Date.now() + 7 * 60 * 60 * 1000;
}

const mode = $('Simpan Token & Mode').first().json;
const { dryRun, token } = mode;
const HEADER = ["tanggal_closing","platform","kategori_biaya","deskripsi","transaction_type_raw","amount","amount_raw","reference_id","id_platform","create_time","synced_at"];
const MAKS_BARIS = 30000;

const PETA = {
  tanggal_closing: "tanggal_closing",
  platform: "platform",
  kategori_biaya: "kategori_biaya",
  deskripsi: "deskripsi",
  transaction_type_raw: "transaction_type_raw",
  amount: "amount",
  amount_raw: "amount_raw",
  reference_id: "reference_id",
  id_platform: "id_platform",
  create_time: "create_time",
  synced_at: "synced_at",
};

const staticData = $getWorkflowStaticData("global");

let cutoffMs;
if (dryRun) {
  // Dry-run TIDAK PERNAH membaca/mengubah penanda tersimpan -- selalu
  // pratinjau 1 hari terakhir berdasarkan synced_at, supaya aman dicoba
  // berkali-kali tanpa risiko menggeser penanda produksi.
  cutoffMs = sekarangJakartaMs() - 1 * 24 * 60 * 60 * 1000;
} else if (staticData.lastSyncedAtMs) {
  cutoffMs = staticData.lastSyncedAtMs;
} else {
  // Belum pernah jalan sebelumnya -- default aman 2 hari ke belakang, BUKAN
  // seluruh isi sheet historis (lihat README soal backfill manual kalau
  // perlu riwayat lebih jauh).
  cutoffMs = sekarangJakartaMs() - 2 * 24 * 60 * 60 * 1000;
}

const barisTerfilter = [];
let maxMsTerkirim = cutoffMs;
for (const item of $input.all()) {
  const row = item.json;
  const ms = parseTanggalFleksibel(row[PETA.synced_at]);
  if (ms === null || ms <= cutoffMs) continue;
  const obj = {};
  for (const kolom of HEADER) obj[kolom] = row[PETA[kolom]] ?? "";
  barisTerfilter.push(obj);
  if (ms > maxMsTerkirim) maxMsTerkirim = ms;
}

if (dryRun) {
  return [{
    json: {
      dryRun: true,
      jumlahBaris: barisTerfilter.length,
      contohBaris: barisTerfilter.slice(0, 3),
      csvHeader: HEADER.join(","),
    },
  }];
}

const hasil = [];
for (let i = 0; i < barisTerfilter.length; i += MAKS_BARIS) {
  const potongan = barisTerfilter.slice(i, i + MAKS_BARIS);
  const lines = [HEADER.join(",")];
  for (const obj of potongan) lines.push(buatBarisCsv(HEADER, obj));
  hasil.push({
    json: {
      dryRun: false,
      token,
      csvText: lines.join("\n") + "\n",
      jumlahBarisBatch: potongan.length,
      batchKe: Math.floor(i / MAKS_BARIS) + 1,
      penandaBaruMs: maxMsTerkirim,
    },
  });
}
if (hasil.length === 0) {
  hasil.push({
    json: {
      dryRun: false,
      token,
      csvText: HEADER.join(",") + "\n",
      jumlahBarisBatch: 0,
      batchKe: 1,
      penandaBaruMs: maxMsTerkirim,
    },
  });
}
return hasil;

// Majukan penanda synced_at HANYA kalau kirim CSV berhasil (HTTP 200) --
// dipanggil cuma di cabang "tidak ada baris gagal" workflow ini, dan TIDAK
// PERNAH dipanggil saat dryRun (cabang dry-run tidak menyentuh node ini sama
// sekali). Baris tanpa id_platform tidak bisa di-dedup di server, jadi
// penanda ini satu-satunya pengaman supaya baris itu tidak terkirim dobel.
const staticData = $getWorkflowStaticData("global");
const items = $input.all();
let maxMs = staticData.lastSyncedAtMs || 0;
for (const item of items) {
  const ms = item.json.penandaBaruMs;
  if (typeof ms === "number" && ms > maxMs) maxMs = ms;
}
staticData.lastSyncedAtMs = maxMs;
return items;
